(() => {
const sheets=[{file:'assets/interior-lab.png',keys:[21,22,26,27,24,25]},{file:'assets/items-lab.png',keys:[31,32,33,34,35,36]}],rects=new Map();
for(const sheet of sheets){const image=new Image();sheet.image=image;image.onload=()=>{const c=document.createElement('canvas');c.width=image.width;c.height=image.height;const cx=c.getContext('2d',{willReadFrequently:true});cx.drawImage(image,0,0);const sw=Math.floor(image.width/3),sh=Math.floor(image.height/2);for(let i=0;i<6;i++){const sx=i%3*sw,sy=Math.floor(i/3)*sh,data=cx.getImageData(sx,sy,sw,sh).data;let l=sw,r=0,t=sh,b=0;for(let y=0;y<sh;y++)for(let x=0;x<sw;x++)if(data[(y*sw+x)*4+3]>100){l=Math.min(l,x);r=Math.max(r,x);t=Math.min(t,y);b=Math.max(b,y)}const entry={image,sx:sx+l,sy:sy+t,w:r-l+1,h:b-t+1};if(sheet.keys[i]===25){let widest=0;entry.baseY=entry.h*.85;entry.baseX=entry.w/2;for(let y=Math.round(t+entry.h*.74);y<Math.round(t+entry.h*.94);y++){let left=sw,right=-1;for(let x=l;x<=r;x++){const k=(y*sw+x)*4;if(data[k+3]>160&&data[k]>data[k+1]*1.12&&data[k+1]>data[k+2]*1.08){left=Math.min(left,x);right=Math.max(right,x)}}if(right-left>widest){widest=right-left;entry.baseY=y-t;entry.baseX=(left+right)/2-l}}}rects.set(sheet.keys[i],entry)}window.gameDebug?.render()};image.src=sheet.file}
window.drawEnvironment=(c,i,mode='portrait')=>{const mini=mode!=='portrait';c.width=mini?128:256;c.height=mini?160:320;const cx=c.getContext('2d');cx.clearRect(0,0,c.width,c.height);cx.setTransform(mini?.5:1,0,0,mini?.5:1,0,0);const r=rects.get(i);if(!r)return;const scale=Math.min((i===25?190:220)/r.w,(mode==='portrait'?288:260)/r.h),w=r.w*scale,h=r.h*scale;cx.drawImage(r.image,r.sx,r.sy,r.w,r.h,i===25&&mode==='figure'?128-r.baseX*scale:128-w/2,i===25&&mode==='figure'?320/1.45-r.baseY*scale:160-h/2,w,h)};
})();
